import{_ as e,o as a,c as s,a2 as d}from"./chunks/framework.DT_qyuxR.js";const m=JSON.parse('{"title":"Capacités & Passifs","description":"","frontmatter":{},"headers":[],"relativePath":"regles/06-capacites.md","filePath":"regles/06-capacites.md"}'),i={name:"regles/06-capacites.md"};function o(n,t,r,l,u,c){return a(),s("div",null,[...t[0]||(t[0]=[d('<h1 id="capacites-passifs" tabindex="-1">Capacités &amp; Passifs <a class="header-anchor" href="#capacites-passifs" aria-label="Permalink to &quot;Capacités &amp; Passifs&quot;">​</a></h1><h2 id="trois-types-de-pouvoirs" tabindex="-1">Trois types de pouvoirs <a class="header-anchor" href="#trois-types-de-pouvoirs" aria-label="Permalink to &quot;Trois types de pouvoirs&quot;">​</a></h2><p>Chaque masque possède jusqu&#39;à trois types de pouvoirs :</p><table tabindex="0"><thead><tr><th>Type</th><th>Moment d&#39;utilisation</th><th>Nombre par partie</th><th>Exemples</th></tr></thead><tbody><tr><td><strong>Attaque de Combat</strong></td><td>En Duel (automatique)</td><td>Illimité</td><td>Aiguillon, Décharge</td></tr><tr><td><strong>Capacité de Jour</strong></td><td>Phase d&#39;Actions de Jour</td><td>1 fois (sauf indication)</td><td>Traque, Percée</td></tr><tr><td><strong>Capacité de Nuit</strong></td><td>Phase de Nuit (en MP)</td><td>1 fois (sauf indication)</td><td>Regard Noir, Métamorphose</td></tr><tr><td><strong>Passif</strong></td><td>Déclenché automatiquement</td><td>Constant ou une fois</td><td>Ronces, Brasier</td></tr></tbody></table><h2 id="capacites-de-jour" tabindex="-1">Capacités de Jour <a class="header-anchor" href="#capacites-de-jour" aria-label="Permalink to &quot;Capacités de Jour&quot;">​</a></h2><p>Les capacités de Jour sont utilisées pendant la phase d&#39;Actions de Jour. Elles sont de deux types :</p><h3 id="actions-immediates" tabindex="-1">Actions immédiates <a class="header-anchor" href="#actions-immediates" aria-label="Permalink to &quot;Actions immédiates&quot;">​</a></h3><p>Appliquées dès la soumission. Exemple :</p><ul><li><strong>Empathique — Baume au coeur</strong> : soigne 3 PV au masque du joueur choisi (immédiat).</li><li><strong>Rage — Rancune</strong> : inflige des dégâts au masque d&#39;un joueur qui vous a défié (immédiat).</li></ul><h3 id="actions-differees-fin-de-journee" tabindex="-1">Actions différées (fin de journée) <a class="header-anchor" href="#actions-differees-fin-de-journee" aria-label="Permalink to &quot;Actions différées (fin de journée)&quot;">​</a></h3><p>Appliquées à la fin de la journée. Exemple :</p><ul><li><strong>Poursuite — Traque</strong> : inflige des dégâts au masque d&#39;un joueur qui n&#39;est pas dans votre salon vocal à la fin de la journée.</li><li><strong>Sacrifice — Percée</strong> : inflige des dégâts escalonnés au masque d&#39;un joueur dans votre salon vocal à la fin de la journée.</li><li><strong>Souvenir — Echo</strong> : inflige 2 dégâts fixes au masque d&#39;un joueur défiez en Duel.</li></ul><h3 id="conditions-vocales" tabindex="-1">Conditions vocales <a class="header-anchor" href="#conditions-vocales" aria-label="Permalink to &quot;Conditions vocales&quot;">​</a></h3><p>Certains masques vérifient la <strong>position vocale</strong> du joueur au moment de la soumission :</p><ul><li><strong>Poursuite</strong> : la cible doit être dans un salon vocal <strong>différent</strong> du vôtre.</li><li><strong>Sacrifice</strong> : la cible doit être dans le <strong>même</strong> salon vocal que vous.</li></ul><blockquote><p><strong>Important</strong> : la vérification vocale est faite au moment de la <strong>soumission</strong>, pas à la résolution. Vous pouvez vous déplacer après avoir soumis l&#39;action.</p></blockquote><h2 id="capacites-de-nuit" tabindex="-1">Capacités de Nuit <a class="header-anchor" href="#capacites-de-nuit" aria-label="Permalink to &quot;Capacités de Nuit&quot;">​</a></h2><p>Les capacités de Nuit sont utilisées pendant la phase de Nuit. Elles sont envoyées en <strong>MP au bot</strong>.</p><h3 id="ordre-de-resolution" tabindex="-1">Ordre de résolution <a class="header-anchor" href="#ordre-de-resolution" aria-label="Permalink to &quot;Ordre de résolution&quot;">​</a></h3><p>Les actions de Nuit sont résolues dans un ordre précis (défini par le champ <code>order</code>) :</p><table tabindex="0"><thead><tr><th>Ordre</th><th>Masque</th><th>Capacité</th><th>Effet</th></tr></thead><tbody><tr><td>1</td><td>Sans-Visage</td><td>Métamorphose</td><td>Copie le masque de la cible</td></tr><tr><td>1</td><td>Messager</td><td>Passerelle</td><td>Envoie un message anonyme</td></tr><tr><td>2</td><td>Abysse</td><td>Regard Noir</td><td>Inflige Maudit</td></tr><tr><td>3</td><td>Rempart</td><td>Forteresse</td><td>Bouclier (réduit les dégâts)</td></tr><tr><td>4</td><td>Maestro</td><td>Crescendo</td><td>Dégâts croissants sur la même cible</td></tr><tr><td>5</td><td>Parasite</td><td>Infestation</td><td>Dégâts + soin continus</td></tr><tr><td>6</td><td>Vampirisme</td><td>Piqûre</td><td>Dégâts + soin</td></tr><tr><td>7</td><td>Courroux</td><td>Fureur</td><td>Dégâts de vengeance</td></tr><tr><td>8</td><td>Éclat</td><td>Radiance</td><td>Dégâts si pas attaqué</td></tr><tr><td>9</td><td>Sommeil</td><td>Berceuse</td><td>Inflige Endormi</td></tr><tr><td>10</td><td>A-Gaz</td><td>Vapeur Nocive</td><td>Dégâts</td></tr><tr><td>11</td><td>Foudre</td><td>Entraves</td><td>Dégâts</td></tr><tr><td>12</td><td>Vampire</td><td>Offrande Sanglante</td><td>Soin</td></tr><tr><td>13</td><td>Medium</td><td>Spiritisme</td><td>Découvre le camp d&#39;un joueur</td></tr><tr><td>14</td><td>Foyer</td><td>Instinct Maternel</td><td>Sélectionne un Enfant</td></tr></tbody></table><h3 id="utilisation-limitee" tabindex="-1">Utilisation limitée <a class="header-anchor" href="#utilisation-limitee" aria-label="Permalink to &quot;Utilisation limitée&quot;">​</a></h3><p>Certaines capacités de Nuit ne peuvent être utilisées <strong>qu&#39;une fois par partie</strong> (indiqué par <code>oncePerGame</code> dans les données). Exemple : Regard Noir de l&#39;Abysse.</p><h3 id="utilisation-a-uses-limites" tabindex="-1">Utilisation à uses limités <a class="header-anchor" href="#utilisation-a-uses-limites" aria-label="Permalink to &quot;Utilisation à uses limités&quot;">​</a></h3><p>D&#39;autres ont un nombre d&#39;utilisations limité (indiqué par <code>limitedUses</code>). Exemple : Forteresse du Rempart.</p><h2 id="passifs" tabindex="-1">Passifs <a class="header-anchor" href="#passifs" aria-label="Permalink to &quot;Passifs&quot;">​</a></h2><p>Les passifs sont des effets <strong>automatiques</strong> déclenchés quand une condition est remplie. Ils ne nécessitent aucune action du joueur.</p><h3 id="types-de-declenchement" tabindex="-1">Types de déclenchement <a class="header-anchor" href="#types-de-declenchement" aria-label="Permalink to &quot;Types de déclenchement&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hook</th><th>Moment</th><th>Exemples</th></tr></thead><tbody><tr><td><code>on_damage_taken</code></td><td>Quand le masque subit des dégâts</td><td>Ronces (Épine)</td></tr><tr><td><code>on_damage_dealt</code></td><td>Quand le masque inflige des dégâts</td><td>Attirance (Foudre), Identification (Sans-Visage)</td></tr><tr><td><code>on_heal_dealt</code></td><td>Quand le masque soigne</td><td>Empathie (Empathique)</td></tr><tr><td><code>on_duel_start</code></td><td>Quand un Duel commence</td><td>Terreur (Effroi), Fournaise (Incendie), Clairvoyance (Oracle)</td></tr><tr><td><code>on_combat_damage_resolve</code></td><td>Après résolution des dégâts de combat</td><td>Lien Familial (Foyer)</td></tr><tr><td><code>on_hp_changed</code></td><td>Quand les PV changent</td><td>Brasier (Incendie)</td></tr><tr><td><code>on_damage_incoming</code></td><td>Avant application des dégâts</td><td>Volonté de pierre (Rocher), L&#39;Indestructible (Inflexible)</td></tr><tr><td><code>on_status_incoming</code></td><td>Quand un statut est appliqué</td><td>Immunité (Chirurgical)</td></tr></tbody></table><h3 id="passifs-a-activation-unique" tabindex="-1">Passifs à activation unique <a class="header-anchor" href="#passifs-a-activation-unique" aria-label="Permalink to &quot;Passifs à activation unique&quot;">​</a></h3><p>Certains passifs ne se déclenchent qu&#39;<strong>une seule fois</strong> :</p><ul><li><strong>Fournaise (Incendie)</strong> : +1 dégât permanent à toutes les attaques de combat, une seule fois.</li><li><strong>Brasier (Incendie)</strong> : +2 dégâts permanents quand les PV tombent sous 6.</li><li><strong>Identification (Sans-Visage)</strong> : révèle le masque de la cible la première fois que vous infligez des dégâts.</li></ul><h3 id="passifs-constants" tabindex="-1">Passifs constants <a class="header-anchor" href="#passifs-constants" aria-label="Permalink to &quot;Passifs constants&quot;">​</a></h3><p>D&#39;autres passifs sont <strong>toujours actifs</strong> :</p><ul><li><strong>Ronces (Épine)</strong> : renvoie des dégâts à l&#39;attaquant.</li><li><strong>Volonté de pierre (Rocher)</strong> : -50% des dégâts de combat subis.</li><li><strong>L&#39;Indestructible (Inflexible)</strong> : -50% de tous les dégâts subis.</li><li><strong>Empathie (Empathique)</strong> : soigne autant que la cible quand vous soignez.</li></ul>',35)])])}const h=e(i,[["render",o]]);export{m as __pageData,h as default};
